package com.freight.logistics.controller;

import com.freight.logistics.document.FreightShipmentDoc;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/mongo/freight/shipments")
public class FreightShipmentQueryController {

    private final MongoTemplate mongoTemplate;

    public FreightShipmentQueryController(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    @GetMapping("/{trackingNumber}")
    public ResponseEntity<FreightShipmentDoc> getShipmentManifest(@PathVariable String trackingNumber) {
        // MongoDB Criteria query searches solely by tracking number without shipper organization constraint
        Query query = new Query(Criteria.where("trackingNumber").is(trackingNumber));
        FreightShipmentDoc shipment = mongoTemplate.findOne(query, FreightShipmentDoc.class);
        if (shipment == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(shipment);
    }
}

